+// Each exchange is an exact command and its wire response. The final read is
+// reported separately: only an actual EOF with no bytes proves a peer hangup.
+type pop3Exchange struct {
+	command, response string
+}
+
+type pop3ScriptResult struct {
+	commands []string
+	err      error
+}
+
+func pop3ScriptServer(t *testing.T, greeting string, exchanges []pop3Exchange, wantEOF bool) (string, <-chan pop3ScriptResult) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatal(err)
+	}
+	results := make(chan pop3ScriptResult, 1)
+	finished := make(chan struct{})
+	var mu sync.Mutex
+	var accepted net.Conn
+	t.Cleanup(func() {
+		ln.Close()
+		mu.Lock()
+		if accepted != nil {
+			accepted.Close()
+		}
+		mu.Unlock()
+		select {
+		case <-finished:
+		case <-time.After(10 * time.Second):
+			t.Error("script server did not stop")
+		}
+	})
+	go func() {
+		defer close(finished)
+		var result pop3ScriptResult
+		defer func() { results <- result }()
+		conn, err := ln.Accept()
+		if err != nil {
+			result.err = err
+			return
+		}
+		defer conn.Close()
+		mu.Lock()
+		accepted = conn
+		mu.Unlock()
+		if err := conn.SetDeadline(time.Now().Add(5 * time.Second)); err != nil {
+			result.err = err
+			return
+		}
+		if _, err := io.WriteString(conn, greeting); err != nil {
+			result.err = err
+			return
+		}
+		br := bufio.NewReader(conn)
+		for _, exchange := range exchanges {
+			line, err := br.ReadString('\n')
+			result.commands = append(result.commands, line)
+			if err != nil {
+				result.err = fmt.Errorf("read command: %w", err)
+				return
+			}
+			if line != exchange.command {
+				result.err = fmt.Errorf("command = %q, want %q", line, exchange.command)
+				return
+			}
+			if _, err := io.WriteString(conn, exchange.response); err != nil {
+				result.err = err
+				return
+			}
+		}
+		if wantEOF {
+			line, err := br.ReadString('\n')
+			if line != "" || err != io.EOF {
+				result.err = fmt.Errorf("after rejection read = (%q, %v), want empty data and EOF", line, err)
+			}
+		}
+	}()
+	return ln.Addr().String(), results
+}
+
+func checkPOP3Script(t *testing.T, results <-chan pop3ScriptResult, exchanges []pop3Exchange) {
+	t.Helper()
+	select {
+	case result := <-results:
+		if result.err != nil {
+			t.Fatalf("script server: %v (commands: %q)", result.err, result.commands)
+		}
+		var want []string
+		for _, exchange := range exchanges {
+			want = append(want, exchange.command)
+		}
+		if !reflect.DeepEqual(result.commands, want) {
+			t.Fatalf("commands = %q, want %q", result.commands, want)
+		}
+	case <-time.After(10 * time.Second):
+		t.Fatal("timed out waiting for script server result")
+	}
+}
+
+func TestPOP3DialAuthenticationContracts(t *testing.T) {
+	for _, tc := range []struct {
+		name      string
+		greeting  string
+		exchanges []pop3Exchange
+		refused   bool
+		authError bool
+	}{
+		{
+			name: "USER rejection", greeting: "+OK ready\r\n", refused: true, authError: true,
+			exchanges: []pop3Exchange{{"USER test-user\r\n", "-ERR unknown user\r\n"}},
+		},
+		{
+			name: "PASS rejection", greeting: "+OK ready\r\n", refused: true, authError: true,
+			exchanges: []pop3Exchange{
+				{"USER test-user\r\n", "+OK user accepted\r\n"},
+				{"PASS test-password\r\n", "-ERR password rejected\r\n"},
+			},
+		},
+		{name: "greeting rejection", greeting: "-ERR unavailable\r\n", refused: true},
+		{
+			name: "successful login", greeting: "+OK ready\r\n",
+			exchanges: []pop3Exchange{
+				{"USER test-user\r\n", "+OK user accepted\r\n"},
+				{"PASS test-password\r\n", "+OK authenticated\r\n"},
+				{"LIST\r\n", "+OK\r\n1 123\r\n2 456\r\n.\r\n"},
+			},
+		},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			addr, results := pop3ScriptServer(t, tc.greeting, tc.exchanges, tc.refused)
+			host, portStr, err := net.SplitHostPort(addr)
+			if err != nil {
+				t.Fatal(err)
+			}
+			port, err := strconv.Atoi(portStr)
+			if err != nil {
+				t.Fatal(err)
+			}
+			password := domain.NewSecretHandle([]byte("test-password"))
+			t.Cleanup(password.Zero)
+			sess, err := (Dialer{}).Dial(context.Background(), domain.POP3DialOptions{
+				Host: host, Port: port, Security: domain.SecurityNone,
+				Username: "test-user", Password: password,
+				ConnectTimeoutSec: 5, CommandTimeoutSec: 5,
+			})
+			if sess != nil {
+				t.Cleanup(func() { sess.Close() })
+			}
+			if tc.refused {
+				if sess != nil || err == nil {
+					t.Fatalf("Dial = (%v, %v), want nil session and error", sess, err)
+				}
+				var authErr *domain.AuthError
+				if got := errors.As(err, &authErr); got != tc.authError {
+					t.Fatalf("AuthError classification = %v, want %v (error: %v)", got, tc.authError, err)
+				}
+				// No client cleanup runs until after this observes the actual EOF.
+				checkPOP3Script(t, results, tc.exchanges)
+				return
+			}
+			if err != nil || sess == nil {
+				t.Fatalf("Dial = (%v, %v), want authenticated session", sess, err)
+			}
+			msgs, err := sess.List(context.Background())
+			want := []domain.RemoteMessage{{Number: 1, Size: 123}, {Number: 2, Size: 456}}
+			if err != nil || !reflect.DeepEqual(msgs, want) {
+				t.Fatalf("LIST = (%+v, %v), want %+v", msgs, err, want)
+			}
+			checkPOP3Script(t, results, tc.exchanges)
+		})
+	}
+}
+
+func TestPOP3BodyDotUnstuffingPreservesFraming(t *testing.T) {
+	const wire = "Subject: dot-stuffed message\r\nX-Test: framing\r\n\r\nordinary body\r\n..foo\r\n..\r\n...bar\r\n.\r\n"
+	const wantBody = "Subject: dot-stuffed message\r\nX-Test: framing\r\n\r\nordinary body\r\n.foo\r\n.\r\n..bar\r\n"
+	for _, tc := range []struct {
+		name    string
+		command string
+		read    func(domain.POP3Session) (io.ReadCloser, error)
+	}{
+		{
+			name: "RETR", command: "RETR 7\r\n",
+			read: func(sess domain.POP3Session) (io.ReadCloser, error) {
+				return sess.Retrieve(context.Background(), 7)
+			},
+		},
+		{
+			name: "TOP", command: "TOP 7 4\r\n",
+			read: func(sess domain.POP3Session) (io.ReadCloser, error) {
+				return sess.Top(context.Background(), 7, 4)
+			},
+		},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			exchanges := []pop3Exchange{
+				{tc.command, "+OK message follows\r\n" + wire},
+				{"LIST\r\n", "+OK\r\n7 321\r\n9 654\r\n.\r\n"},
+			}
+			addr, results := pop3ScriptServer(t, "+OK ready\r\n", exchanges, false)
+			sess := dial(t, addr)
+			t.Cleanup(func() { sess.Close() })
+			body, err := tc.read(sess)
+			if err != nil {
+				t.Fatal(err)
+			}
+			t.Cleanup(func() { body.Close() })
+			got, err := io.ReadAll(body)
+			if err != nil {
+				t.Fatal(err)
+			}
+			if !bytes.Equal(got, []byte(wantBody)) {
+				t.Fatalf("body = %q, want %q", got, wantBody)
+			}
+			msgs, err := sess.List(context.Background())
+			want := []domain.RemoteMessage{{Number: 7, Size: 321}, {Number: 9, Size: 654}}
+			if err != nil || !reflect.DeepEqual(msgs, want) {
+				t.Fatalf("LIST after body = (%+v, %v), want %+v", msgs, err, want)
+			}
+			checkPOP3Script(t, results, exchanges)
+		})
+	}
+}

  1	// Package pop3 implements a minimal RFC 1939 client behind the
  2	// domain.POP3Dialer port. Supports implicit TLS (995), STLS upgrade, and —
  3	// for offline / air-gapped networks — plaintext with optional
  4	// authentication. Policy gating for insecure modes happens in the
  5	// application layer, not here.
  6	package pop3
  7	
  8	import (
  9		"bytes"
 10		"context"
 11		"crypto/tls"
 12		"fmt"
 13		"io"
 14		"net"
 15		"net/textproto"
 16		"strconv"
 17		"strings"
 18		"time"
 19	
 20		"postra/internal/domain"
 21	)
 22	
 23	// maxListBytes caps how much of one multi-line response (LIST, UIDL) readList
 24	// may accumulate. Nothing else bounds it: readList collects lines until the
 25	// server sends the terminating ".", and it refreshes the command deadline on
 26	// every line it reads, so a server that keeps dribbling short lines and never
 27	// terminates the response holds the collecting worker for ever with no deadline
 28	// left to stop it. That is worse here than on the IMAP side, where the same
 29	// shape was closed in v0.23.7: readList runs in the enumeration step (the sync
 30	// loop's UIDL, then LIST), so one such maildrop stalls a whole account's sync
 31	// before the first message is touched.
 32	//
 33	// The bound has to clear the biggest legitimate maildrop, which arrives in a
 34	// single response: a UIDL line is a message number, a space and a unique-id of
 35	// at most 70 characters (RFC 1939 §7), charged at 92 bytes per message by
 36	// TestPOP3FullMaildropStaysUnderListBound. 32 MiB therefore leaves room for
 37	// roughly 364,000 messages in one maildrop while still bounding a runaway
 38	// response — 8 MiB, the IMAP figure, would refuse a maildrop of 91,000.
 39	const maxListBytes = 32 << 20
 40	
 41	// listLineOverhead is what every line of a multi-line response costs on top of
 42	// the bytes textproto.ReadLine returns, and without it maxListBytes does not
 43	// hold. A line arrives with its CRLF already stripped, so a bare "\r\n" measures
 44	// zero: charging only len(line), a server that answers with nothing but blank
 45	// lines never advances the total at all and readList appends "" for ever, which
 46	// is the runaway the bound exists to stop. A retained line also costs a 16-byte
 47	// string header in lines, so at one byte per line a 32 MiB total would sit on
 48	// far more live heap than the bound suggests. Charging the two bytes the server
 49	// really sent plus that header closes both. The IMAP adapter carries the same
 50	// constant as responseLineOverhead, added for exactly this bypass.
 51	const listLineOverhead = 2 + 16
 52	
 53	type Dialer struct{}
 54	
 55	func (Dialer) Dial(ctx context.Context, opts domain.POP3DialOptions) (domain.POP3Session, error) {
 56		addr := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
 57		connectTO := secondsOr(opts.ConnectTimeoutSec, 15)
 58		d := &net.Dialer{Timeout: connectTO}
 59	
 60		var conn net.Conn
 61		var err error
 62		tlsCfg := &tls.Config{
 63			ServerName: opts.Host,
 64			MinVersion: tls.VersionTLS12,
 65			// #nosec G402 -- offline/self-hosted POP3 servers may use self-signed
 66			// certs; skipping verification is an explicit per-account opt-in
 67			// (default false), required by offline-network mail support.
 68			InsecureSkipVerify: opts.InsecureSkipVerify,
 69		}
 70		switch opts.Security {
 71		case domain.SecurityTLS:
 72			conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
 73		case domain.SecurityStartTLS, domain.SecurityNone:
 74			conn, err = d.DialContext(ctx, "tcp", addr)
 75		default:
 76			return nil, fmt.Errorf("unknown security mode %q", opts.Security)
 77		}
 78		if err != nil {
 79			return nil, fmt.Errorf("pop3 connect %s: %w", addr, err)
 80		}
 81	
 82		s := &session{
 83			conn:      conn,
 84			text:      textproto.NewConn(conn),
 85			commandTO: secondsOr(opts.CommandTimeoutSec, 60),
 86		}
 87		if _, err := s.readResponse(); err != nil {
 88			conn.Close()
 89			return nil, fmt.Errorf("pop3 greeting: %w", err)
 90		}
 91	
 92		if opts.Security == domain.SecurityStartTLS {
 93			if _, err := s.cmd("STLS"); err != nil {
 94				conn.Close()
 95				return nil, fmt.Errorf("STLS: %w", err)
 96			}
 97			// TLS is client-speaks-first: after the "+OK" that grants the upgrade a
 98			// conforming server sends nothing until it has seen the ClientHello. So
 99			// anything already sitting in the reader is plaintext the server pushed
100			// ahead of the handshake — a STARTTLS command injection (CVE-2011-0411
101			// and the 2021 "NO STARTTLS" survey), whose payload the upgrade below
102			// would otherwise discard along with the old reader, leaving the session
103			// to continue as if nothing had happened. Refusing is the safe verdict,
104			// and it cannot cost a well-behaved server anything.
105			//
106			// Best-effort by construction: only bytes that reached this buffer are
107			// visible, so an injection still in flight in the kernel or on the wire
108			// goes unseen. It narrows the window rather than closing it.
109			if n := s.text.R.Buffered(); n > 0 {
110				conn.Close()
111				return nil, fmt.Errorf("STLS: server sent %d bytes before TLS handshake", n)
112			}
113			tconn := tls.Client(conn, tlsCfg)
114			if err := tconn.HandshakeContext(ctx); err != nil {
115				conn.Close()
116				return nil, fmt.Errorf("STLS handshake: %w", err)
117			}
118			s.conn = tconn
119			s.text = textproto.NewConn(tconn)
120		}
121	
122		// Authentication is optional: some maildrops on isolated networks accept
123		// sessions without USER/PASS.
124		if opts.Username != "" {
125			if _, err := s.cmd("USER %s", opts.Username); err != nil {
126				s.Close()
127				return nil, &AuthError{Err: fmt.Errorf("USER: %w", err)}
128			}
129			pass := ""
130			if opts.Password != nil {
131				pass = string(opts.Password.Reveal())
132			}
133			_, err := s.cmd("PASS %s", pass)
134			pass = ""
135			_ = pass
136			if err != nil {
137				s.Close()
138				return nil, &AuthError{Err: fmt.Errorf("PASS rejected: %w", err)}
139			}
140		}
141		return s, nil
142	}
143	
144	// AuthError aliases the shared domain type so the sync layer can recognize
145	// credential failures from any inbound adapter (POP-011).
146	type AuthError = domain.AuthError
147	
148	type session struct {
149		conn      net.Conn
150		text      *textproto.Conn
151		commandTO time.Duration
152	}
153	
154	func (s *session) deadline() { s.conn.SetDeadline(time.Now().Add(s.commandTO)) }
155	
156	func (s *session) readResponse() (string, error) {
157		s.deadline()
158		line, err := s.text.ReadLine()
159		if err != nil {
160			return "", err
161		}
162		if !strings.HasPrefix(line, "+OK") {
163			return "", fmt.Errorf("server: %s", line)
164		}
165		return line, nil
166	}
167	
168	func (s *session) cmd(format string, args ...any) (string, error) {
169		s.deadline()
170		if err := s.text.PrintfLine(format, args...); err != nil {
171			return "", err
172		}
173		return s.readResponse()
174	}
175	
176	// readList collects a multi-line response up to its "." terminator, bounded by
177	// maxListBytes so an unterminated response cannot hold the session for ever.
178	func (s *session) readList() ([]string, error) {
179		var lines []string
180		var charged int64
181		for {
182			s.deadline()
183			line, err := s.text.ReadLine()
184			if err != nil {
185				return nil, err
186			}
187			if line == "." {
188				return lines, nil
189			}
190			charged += int64(len(line)) + listLineOverhead
191			if charged > maxListBytes {
192				// The rest of the response is still on the wire and its length is
193				// unknown, so the offset the next command would read at is
194				// unknowable: discard the session rather than let a later command
195				// mistake those bytes for its own reply.
196				s.conn.Close()
197				return nil, fmt.Errorf("pop3 multi-line response exceeds %d bytes", int64(maxListBytes))
198			}
199			lines = append(lines, strings.TrimPrefix(line, "."))
200		}
201	}
202	
203	func (s *session) List(ctx context.Context) ([]domain.RemoteMessage, error) {
204		if _, err := s.cmd("LIST"); err != nil {
205			return nil, err
206		}
207		lines, err := s.readList()
208		if err != nil {
209			return nil, err
210		}
211		var out []domain.RemoteMessage
212		for _, l := range lines {
213			var n int
214			var size int64
215			if _, err := fmt.Sscanf(l, "%d %d", &n, &size); err == nil {
216				out = append(out, domain.RemoteMessage{Number: n, Size: size})
217			}
218		}
219		return out, nil
220	}
221	
222	func (s *session) UIDL(ctx context.Context) ([]domain.RemoteMessage, error) {
223		if _, err := s.cmd("UIDL"); err != nil {
224			return nil, err // caller falls back to LIST + content hash (POP-005)
225		}
226		lines, err := s.readList()
227		if err != nil {
228			return nil, err
229		}
230		var out []domain.RemoteMessage
231		for _, l := range lines {
232			parts := strings.SplitN(strings.TrimSpace(l), " ", 2)
233			if len(parts) != 2 {
234				continue
235			}
236			n, err := strconv.Atoi(parts[0])
237			if err != nil {
238				continue
239			}
240			out = append(out, domain.RemoteMessage{Number: n, UIDL: strings.TrimSpace(parts[1])})
241		}
242		return out, nil
243	}
244	
245	// retrBody reads a multi-line response body with dot-unstuffing.
246	func (s *session) retrBody() (io.ReadCloser, error) {
247		var buf bytes.Buffer
248		for {
249			s.deadline()
250			line, err := s.text.ReadLineBytes()
251			if err != nil {
252				return nil, err
253			}
254			if len(line) == 1 && line[0] == '.' {
255				break
256			}
257			if len(line) > 1 && line[0] == '.' {
258				line = line[1:]
259			}
260			buf.Write(line)
261			buf.WriteString("\r\n")
262		}
263		return io.NopCloser(&buf), nil
264	}
265	
266	func (s *session) Retrieve(ctx context.Context, number int) (io.ReadCloser, error) {
267		if _, err := s.cmd("RETR %d", number); err != nil {
268			return nil, err
269		}
270		return s.retrBody()
271	}
272	
273	func (s *session) Top(ctx context.Context, number, lines int) (io.ReadCloser, error) {
274		if _, err := s.cmd("TOP %d %d", number, lines); err != nil {
275			return nil, err
276		}
277		return s.retrBody()
278	}
279	
280	func (s *session) Delete(ctx context.Context, number int) error {
281		_, err := s.cmd("DELE %d", number)
282		return err
283	}
284	
285	func (s *session) Quit(ctx context.Context) error {
286		_, err := s.cmd("QUIT")
287		s.conn.Close()
288		return err
289	}
290	
291	func (s *session) Close() error { return s.conn.Close() }
292	
293	func secondsOr(v, def int) time.Duration {
294		if v <= 0 {
295			v = def
296		}
297		return time.Duration(v) * time.Second
298	}

