 28	// dial connects to a scripted server on 127.0.0.1 with the real Dialer. An
 29	// empty username skips USER/PASS, which keeps the fixtures to the multi-line
 30	// framing these tests are about.
 31	func dial(t *testing.T, addr string) domain.POP3Session {
 32		t.Helper()
 33		host, portStr, err := net.SplitHostPort(addr)
 34		if err != nil {
 35			t.Fatal(err)
 36		}
 37		port, err := strconv.Atoi(portStr)
 38		if err != nil {
 39			t.Fatal(err)
 40		}
 41		sess, err := Dialer{}.Dial(context.Background(), domain.POP3DialOptions{
 42			Host: host, Port: port, Security: domain.SecurityNone,
 43		})
 44		if err != nil {
 45			t.Fatalf("dial: %v", err)
 46		}
 47		return sess
 48	}
 49	
 50	// maildropServer answers UIDL and LIST with scripted, properly "."-terminated
 51	// multi-line responses. Anything else gets a bare +OK.
 52	func maildropServer(t *testing.T, uidl, list string) string {
 53		t.Helper()
 54		ln, err := net.Listen("tcp", "127.0.0.1:0")
 55		if err != nil {
 56			t.Fatal(err)
 57		}
 58		t.Cleanup(func() { ln.Close() })
 59		go func() {
 60			conn, err := ln.Accept()
 61			if err != nil {
 62				return
 63			}
 64			defer conn.Close()
 65			br := bufio.NewReader(conn)
 66			io.WriteString(conn, "+OK POP3 ready\r\n")
 67			for {
 68				line, err := br.ReadString('\n')
 69				if err != nil {
 70					return
 71				}
 72				fields := strings.Fields(line)
 73				if len(fields) == 0 {
 74					continue
 75				}
 76				switch strings.ToUpper(fields[0]) {
 77				case "UIDL":
 78					io.WriteString(conn, "+OK\r\n"+uidl+".\r\n")
 79				case "LIST":
 80					io.WriteString(conn, "+OK\r\n"+list+".\r\n")
 81				case "QUIT":
 82					io.WriteString(conn, "+OK bye\r\n")
 83					return
 84				default:
 85					io.WriteString(conn, "+OK\r\n")
 86				}
 87			}
 88		}()
 89		return ln.Addr().String()
 90	}
