 92	// selfSigned builds a throwaway server certificate for the STLS fixtures. Ported
 93	// from internal/adapters/smtp/client_test.go, which upgrades the same way.
 94	func selfSigned(t *testing.T) *tls.Config {
 95		t.Helper()
 96		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
 97		if err != nil {
 98			t.Fatal(err)
 99		}
100		tmpl := &x509.Certificate{
101			SerialNumber: big.NewInt(1),
102			Subject:      pkix.Name{CommonName: "127.0.0.1"},
103			NotBefore:    time.Now().Add(-time.Hour),
104			NotAfter:     time.Now().Add(time.Hour),
105			IPAddresses:  []net.IP{net.ParseIP("127.0.0.1")},
106			KeyUsage:     x509.KeyUsageDigitalSignature,
107			ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
108		}
109		der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
110		if err != nil {
111			t.Fatal(err)
112		}
113		return &tls.Config{Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key}}, MinVersion: tls.VersionTLS12}
114	}
