116	// stlsServer answers STLS and upgrades, then serves UIDL and LIST over TLS from
117	// the same loop. inject is appended to the STLS "+OK" in the same write, so the
118	// injected plaintext reaches the client together with the response it is
119	// already reading — the shape of a STARTTLS command-injection attempt. The
120	// returned channel is closed when the server's connection handler returns,
121	// which is how the tests observe the client hanging up.
122	func stlsServer(t *testing.T, inject, uidl, list string) (string, <-chan struct{}) {
123		t.Helper()
124		tlsCfg := selfSigned(t)
125		ln, err := net.Listen("tcp", "127.0.0.1:0")
126		if err != nil {
127			t.Fatal(err)
128		}
129		t.Cleanup(func() { ln.Close() })
130		done := make(chan struct{})
131		go func() {
132			defer close(done)
133			conn, err := ln.Accept()
134			if err != nil {
135				return
136			}
137			defer conn.Close()
138			conn.SetDeadline(time.Now().Add(20 * time.Second))
139			br := bufio.NewReader(conn)
140			var w io.Writer = conn
141			io.WriteString(w, "+OK POP3 ready\r\n")
142			for {
143				line, err := br.ReadString('\n')
144				if err != nil {
145					return
146				}
147				fields := strings.Fields(line)
148				if len(fields) == 0 {
149					continue
150				}
151				switch strings.ToUpper(fields[0]) {
152				case "STLS":
153					if _, err := io.WriteString(w, "+OK begin TLS negotiation\r\n"+inject); err != nil {
154						return
155					}
156					tconn := tls.Server(conn, tlsCfg)
157					if err := tconn.Handshake(); err != nil {
158						return
159					}
160					br = bufio.NewReader(tconn)
161					w = tconn
162				case "UIDL":
163					io.WriteString(w, "+OK\r\n"+uidl+".\r\n")
164				case "LIST":
165					io.WriteString(w, "+OK\r\n"+list+".\r\n")
166				case "QUIT":
167					io.WriteString(w, "+OK bye\r\n")
168					return
169				default:
170					io.WriteString(w, "+OK\r\n")
171				}
172			}
173		}()
174		return ln.Addr().String(), done
175	}
