195	// TestPOP3STLSInjectedPlaintextRefusesUpgrade pins the pre-handshake check. TLS
196	// is client-speaks-first, so a server that has anything left to say after its
197	// STLS "+OK" is injecting plaintext into the session. Without the check the
198	// upgrade replaces the reader and the injected bytes are dropped silently, so
199	// Dial succeeds and nothing records that the server broke the protocol.
200	func TestPOP3STLSInjectedPlaintextRefusesUpgrade(t *testing.T) {
201		addr, done := stlsServer(t, "+OK injected\r\n", "1 abc\r\n", "1 10\r\n")
202	
203		sess, err := dialStartTLS(t, addr)
204		if err == nil {
205			sess.Close()
206			t.Fatal("Dial accepted a server that injected plaintext before the STLS handshake")
207		}
208		if !strings.Contains(err.Error(), "before TLS handshake") {
209			t.Fatalf("Dial error = %v, want it to name the pre-handshake bytes", err)
210		}
211	
212		// The connection must be gone, not left dangling in plaintext.
213		select {
214		case <-done:
215		case <-time.After(10 * time.Second):
216			t.Fatal("server connection still open after the refused upgrade; want the client to have closed it")
217		}
218	}
