221	// on a well-behaved server would stop mail collection outright. A clean upgrade
222	// must still authenticate nothing, negotiate TLS, and answer UIDL and LIST on
223	// the encrypted connection.
224	func TestPOP3STLSUpgradeRunsCommandsOverTLS(t *testing.T) {
225		addr, _ := stlsServer(t, "", "1 uid-one\r\n2 uid-two\r\n", "1 2048\r\n2 4096\r\n")
