232		ctx := context.Background()
233	
234		msgs, err := sess.UIDL(ctx)
235		if err != nil {
236			t.Fatalf("UIDL after the upgrade: %v", err)
237		}
238		if len(msgs) != 2 || msgs[0].UIDL != "uid-one" || msgs[1].UIDL != "uid-two" {
239			t.Fatalf("UIDL = %+v, want uid-one and uid-two", msgs)
