253	// endlessListServer accepts a command, answers +OK, and then repeats one line
254	// for as long as the client keeps reading — it never sends the "." that ends a
255	// multi-line response.
256	func endlessListServer(t *testing.T, repeated string) string {
257		t.Helper()
258		ln, err := net.Listen("tcp", "127.0.0.1:0")
259		if err != nil {
260			t.Fatal(err)
261		}
262		stop := make(chan struct{})
263		t.Cleanup(func() { close(stop); ln.Close() })
264		var batch strings.Builder
265		for batch.Len() < 4096 {
266			batch.WriteString(repeated)
267		}
268		payload := batch.String()
269		go func() {
270			conn, err := ln.Accept()
271			if err != nil {
272				return
273			}
274			defer conn.Close()
275			br := bufio.NewReader(conn)
276			io.WriteString(conn, "+OK POP3 ready\r\n")
277			for {
278				line, err := br.ReadString('\n')
279				if err != nil {
280					return
281				}
282				if len(strings.Fields(line)) == 0 {
283					continue
284				}
285				io.WriteString(conn, "+OK\r\n")
286				for {
287					select {
288					case <-stop:
289						return
290					default:
291					}
292					if _, err := io.WriteString(conn, payload); err != nil {
293						return
294					}
295				}
296			}
297		}()
298		return ln.Addr().String()
299	}
