301	// TestPOP3EndlessListResponseDiscardsSession pins the bound readList needs.
302	// readList collects lines until the server sends "." and refreshes the command
303	// deadline on every line, so a server that dribbles short lines for ever is
304	// never stopped by the 60-second command timeout — the enumeration step hangs
305	// and the collected lines grow without limit.
306	func TestPOP3EndlessListResponseDiscardsSession(t *testing.T) {
307		sess := dial(t, endlessListServer(t, "1 0123456789abcdef0123\r\n"))
308		defer sess.Close()
309		ctx := context.Background()
310	
311		started := time.Now()
312		_, err := sess.UIDL(ctx)
313		elapsed := time.Since(started)
314	
315		if err == nil {
316			t.Fatal("UIDL over an unterminated multi-line response returned no error")
317		}
318		if !strings.Contains(err.Error(), "multi-line response exceeds") {
319			t.Fatalf("UIDL error = %v, want it to name the multi-line response bound", err)
320		}
321		if elapsed > 30*time.Second {
322			t.Fatalf("UIDL took %v to give up; want the bound to stop it well inside the 60s command timeout", elapsed)
323		}
324	
325		// The rest of the response is still on the wire, so the session cannot be
326		// reused: both remaining commands must fail rather than read those bytes as
327		// protocol.
328		if _, err := sess.List(ctx); err == nil {
329			t.Fatal("List on the discarded session succeeded; want an error")
330		}
331		if _, err := sess.Retrieve(ctx, 1); err == nil {
332			t.Fatal("Retrieve on the discarded session succeeded; want an error")
333		}
334	}
