336	// TestPOP3EndlessBlankLinesDiscardSession is the same attack with the cheapest
337	// line there is. textproto.ReadLine strips the CRLF, so a bare "\r\n" comes back
338	// as zero bytes: an accounting that charges only len(line) never advances at all
339	// and readList appends "" for ever while the deadline keeps being pushed out.
340	// Charging every line the terminator it really cost plus the header it occupies
341	// is what makes the bound reachable here — the IMAP adapter took a review for
342	// exactly this bypass.
343	func TestPOP3EndlessBlankLinesDiscardSession(t *testing.T) {
344		sess := dial(t, endlessListServer(t, "\r\n"))
345		defer sess.Close()
346		ctx := context.Background()
347	
348		started := time.Now()
349		_, err := sess.UIDL(ctx)
350		elapsed := time.Since(started)
351	
352		if err == nil {
353			t.Fatal("UIDL over an endless run of blank lines returned no error")
354		}
355		if !strings.Contains(err.Error(), "multi-line response exceeds") {
356			t.Fatalf("UIDL error = %v, want it to name the multi-line response bound", err)
357		}
358		if elapsed > 30*time.Second {
359			t.Fatalf("UIDL took %v to give up; want the bound to stop it well inside the 60s command timeout", elapsed)
360		}
