363	// TestPOP3FullMaildropStaysUnderListBound is the regression guard on the bound's
364	// size. A large maildrop is enumerated in one multi-line response, so the bound
365	// has to clear the biggest legitimate one by a wide margin. It measures what a
366	// full-length UIDL response actually costs against the bound and fails if the
367	// margin closes — and proves the normal path still parses byte-for-byte.
368	func TestPOP3FullMaildropStaysUnderListBound(t *testing.T) {
369		const count = 5000
370		const uidPrefix = "uuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuu" // 65 chars; + %05d = the RFC 1939 maximum of 70
371		var uidl, list strings.Builder
372		for i := 1; i <= count; i++ {
373			fmt.Fprintf(&uidl, "%d %s%05d\r\n", i, uidPrefix, i)
374			fmt.Fprintf(&list, "%d %d\r\n", i, 2048+i)
375		}
376		wire := uidl.String()
377	
378		sess := dial(t, maildropServer(t, wire, list.String()))
379		defer sess.Close()
380		ctx := context.Background()
381	
382		msgs, err := sess.UIDL(ctx)
383		if err != nil {
384			t.Fatalf("enumerate a %d-message maildrop (%d bytes of UIDL response): %v", count, len(wire), err)
385		}
386		if len(msgs) != count {
387			t.Fatalf("UIDL returned %d messages, want %d", len(msgs), count)
388		}
389		for i, m := range msgs {
390			wantN := i + 1
391			wantUID := fmt.Sprintf("%s%05d", uidPrefix, wantN)
392			if m.Number != wantN || m.UIDL != wantUID {
393				t.Fatalf("UIDL entry %d = {Number:%d UIDL:%q}, want {Number:%d UIDL:%q}", i, m.Number, m.UIDL, wantN, wantUID)
394			}
395		}
396		sizes, err := sess.List(ctx)
397		if err != nil {
398			t.Fatalf("list a %d-message maildrop: %v", count, err)
399		}
400		if len(sizes) != count {
401			t.Fatalf("LIST returned %d messages, want %d", len(sizes), count)
402		}
403		for i, m := range sizes {
404			if m.Number != i+1 || m.Size != int64(2048+i+1) {
405				t.Fatalf("LIST entry %d = {Number:%d Size:%d}, want {Number:%d Size:%d}", i, m.Number, m.Size, i+1, 2048+i+1)
406			}
407		}
408	
409		// What that response cost the bound: the CRLF is stripped before the line is
410		// charged and re-charged as part of listLineOverhead.
411		charged := int64(len(wire)-2*count) + int64(count)*listLineOverhead
412		perMessage := charged / count
413		t.Logf("a %d-message UIDL response is %d bytes on the wire, charged %d against the %d-byte bound (%d per message, so the bound admits %d messages)",
414			count, len(wire), charged, int64(maxListBytes), perMessage, int64(maxListBytes)/perMessage)
415		if charged*8 > maxListBytes {
416			t.Fatalf("a %d-message enumeration is charged %d bytes, within 8x of the %d-byte bound; the bound leaves no margin", count, charged, int64(maxListBytes))
417		}
418		// The real sizing constraint is maildrop scale, not this fixture: a bound
419		// that cannot hold a few hundred thousand maximum-length UIDs would break
420		// real maildrops rather than runaway servers.
421		const wantMessages = 300000
422		if perMessage*wantMessages > maxListBytes {
423			t.Fatalf("at %d charged bytes per message the %d-byte bound admits only %d messages, fewer than the %d a large maildrop holds",
424				perMessage, int64(maxListBytes), int64(maxListBytes)/perMessage, wantMessages)
425		}
426	}
