428	// Each exchange is an exact command and its wire response. The final read is
429	// reported separately: only an actual EOF with no bytes proves a peer hangup.
430	type pop3Exchange struct {
431		command, response string
432	}
433	
434	type pop3ScriptResult struct {
435		commands []string
436		err      error
437	}
438	
439	func pop3ScriptServer(t *testing.T, greeting string, exchanges []pop3Exchange, wantEOF bool) (string, <-chan pop3ScriptResult) {
440		t.Helper()
441		ln, err := net.Listen("tcp", "127.0.0.1:0")
442		if err != nil {
443			t.Fatal(err)
444		}
445		results := make(chan pop3ScriptResult, 1)
446		finished := make(chan struct{})
447		var mu sync.Mutex
448		var accepted net.Conn
449		t.Cleanup(func() {
450			ln.Close()
451			mu.Lock()
452			if accepted != nil {
453				accepted.Close()
454			}
455			mu.Unlock()
456			select {
457			case <-finished:
458			case <-time.After(10 * time.Second):
459				t.Error("script server did not stop")
460			}
461		})
462		go func() {
463			defer close(finished)
464			var result pop3ScriptResult
465			defer func() { results <- result }()
466			conn, err := ln.Accept()
467			if err != nil {
468				result.err = err
469				return
470			}
471			defer conn.Close()
472			mu.Lock()
473			accepted = conn
474			mu.Unlock()
475			if err := conn.SetDeadline(time.Now().Add(5 * time.Second)); err != nil {
476				result.err = err
477				return
478			}
479			if _, err := io.WriteString(conn, greeting); err != nil {
480				result.err = err
481				return
482			}
483			br := bufio.NewReader(conn)
484			for _, exchange := range exchanges {
485				line, err := br.ReadString('\n')
486				result.commands = append(result.commands, line)
487				if err != nil {
488					result.err = fmt.Errorf("read command: %w", err)
489					return
490				}
491				if line != exchange.command {
492					result.err = fmt.Errorf("command = %q, want %q", line, exchange.command)
493					return
494				}
495				if _, err := io.WriteString(conn, exchange.response); err != nil {
496					result.err = err
497					return
498				}
499			}
500			if wantEOF {
501				line, err := br.ReadString('\n')
502				if line != "" || err != io.EOF {
503					result.err = fmt.Errorf("after rejection read = (%q, %v), want empty data and EOF", line, err)
504				}
505			}
506		}()
507		return ln.Addr().String(), results
508	}
509	
510	func checkPOP3Script(t *testing.T, results <-chan pop3ScriptResult, exchanges []pop3Exchange) {
511		t.Helper()
512		select {
513		case result := <-results:
514			if result.err != nil {
515				t.Fatalf("script server: %v (commands: %q)", result.err, result.commands)
516			}
517			var want []string
518			for _, exchange := range exchanges {
519				want = append(want, exchange.command)
520			}
521			if !reflect.DeepEqual(result.commands, want) {
522				t.Fatalf("commands = %q, want %q", result.commands, want)
523			}
524		case <-time.After(10 * time.Second):
525			t.Fatal("timed out waiting for script server result")
526		}
527	}
